def is_prime(n):
    # ตรวจสอบว่า n เป็นจำนวนเต็มบวกหรือไม่
    if n <= 1:
        return False
    # จำนวนเฉพาะต้องมากกว่า 1
    if n <= 3:
        return True
    # ลบเลข 2 และ 3 ออก
    if n % 2 == 0 or n % 3 == 0:
        return False

    # ตรวจสอบเฉพาะจำนวนที่หารด้วย 6 ได้ (6k ± 1)
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True
